// Turn getUpdates into at most one item per command.
//
// Authorisation happens here and is repeated in SQL. docs/telegram.md: a
// message from any other chat is ignored - not answered, not treated as an
// error. It is still recorded in command_log, because a command arriving from
// a chat that is not yours is how you find out the bot token has leaked, and
// a record is not the same as an answer.

const CHAT_ID = String($env.TELEGRAM_CHAT_ID || '').trim();
const body = $input.first().json;

if (!body || body.ok !== true || !Array.isArray(body.result) || body.result.length === 0) {
  return [];
}

const out = [];
for (const update of body.result) {
  const msg = update.message || update.edited_message;
  if (!msg || typeof msg.text !== 'string') continue;

  const text = msg.text.trim();
  if (!text.startsWith('/')) continue;

  // "/approve 7f3a" and "/approve@my_bot 7f3a" are the same command: Telegram
  // appends the bot name when several bots share a group.
  const parts = text.slice(1).split(/\s+/);
  // Words people actually type for the same thing. command_log shows
  // "/accept" arriving on 2026-09-23 and being answered "unknown"; /start is
  // what Telegram sends when a chat with the bot is opened.
  const ALIASES = { accept: 'approve', ok: 'approve', decline: 'reject', start: 'help', commands: 'help',
                   funnel: 'stats', revenue: 'stats' };
  const typed = parts[0].split('@')[0].toLowerCase();
  const command = ALIASES[typed] || typed;
  const argument = parts[1] || null;
  const reason = parts.slice(2).join(' ') || null;

  out.push({
    json: {
      update_id: update.update_id,
      chat_id: String(msg.chat && msg.chat.id),
      command,
      argument,
      reason,
      // Every word after the command: /approve takes several ids, /stage an id,
      // a stage, a value and a note.
      args: parts.slice(1).filter(Boolean),
      authorised: CHAT_ID !== '' && String(msg.chat && msg.chat.id) === CHAT_ID,
    },
  });
}

// Highest update_id last, so Save Offset converges on the right number even
// though it runs once per item.
out.sort((a, b) => a.json.update_id - b.json.update_id);
return out;
